// Extract clean text and PDF links from HTML
const html = $input.first().json.data || $input.first().json.body || $input.first().json;
const htmlString = typeof html === "string" ? html : JSON.stringify(html);

const baseUrl = "https://inginerie.ulbsibiu.ro/dep.cie/";

let cleanText = htmlString;

// FOLOSIM CODURI HEXADECIMALE pentru a evita eroarea "missing )"
// \x3C înseamnă <
// \x3E înseamnă >
// Astfel, parser-ul n8n nu mai confundă codul cu tag-uri HTML reale.
cleanText = cleanText.replace(/\x3Cscript[\s\S]*?\x3C\/script\x3E/gi, "");
cleanText = cleanText.replace(/\x3Cstyle[\s\S]*?\x3C\/style\x3E/gi, "");
cleanText = cleanText.replace(/\x3Cnav[\s\S]*?\x3C\/nav\x3E/gi, "");
cleanText = cleanText.replace(/\x3Cfooter[\s\S]*?\x3C\/footer\x3E/gi, "");
cleanText = cleanText.replace(/\x3Cheader[\s\S]*?\x3C\/header\x3E/gi, "");
cleanText = cleanText.replace(/\x3C!--[\s\S]*?--\x3E/g, "");

// ACEASTA ESTE LINIA CARE DĂDEA CRASH, acum rescrisă în format sigur:
cleanText = cleanText.replace(/\x3C[^\x3E]+\x3E/g, " ");

// Curățăm entitățile HTML
cleanText = cleanText.replace(/&nbsp;/g, " ");
cleanText = cleanText.replace(/&amp;/g, "&");
cleanText = cleanText.replace(/&lt;/g, "<");
cleanText = cleanText.replace(/&gt;/g, ">");
cleanText = cleanText.replace(/&quot;/g, '"');
cleanText = cleanText.replace(/&#39;/g, "'");

// Eliminăm spațiile suplimentare
cleanText = cleanText.replace(/\s+/g, " ");
cleanText = cleanText.trim();

// Limităm cantitatea de text
if (cleanText.length > 50000) {
  cleanText = cleanText.substring(0, 50000);
}

// Extragem linkurile PDF (aici nu foloseam < > deci e în siguranță)
const pdfLinks = [];
const linkRegex = /href=["']([^"']+\.pdf[^"']*)["']/gi;
let match;

while ((match = linkRegex.exec(htmlString)) !== null) {
  let pdfUrl = match[1];

  if (pdfUrl.startsWith("//")) {
    pdfUrl = "https:" + pdfUrl;
  } else if (pdfUrl.startsWith("/")) {
    pdfUrl = "https://inginerie.ulbsibiu.ro" + pdfUrl;
  } else if (!pdfUrl.startsWith("http")) {
    pdfUrl = baseUrl + pdfUrl;
  }

  let parts = pdfUrl.split("/");
  let lastPart = parts[parts.length - 1];
  let fileName = lastPart.split("?")[0];

  if (!fileName) {
    fileName = "document_" + (pdfLinks.length + 1) + ".pdf";
  }

  pdfLinks.push({
    url: pdfUrl,
    fileName: fileName
  });
}

// Filtrăm PDF-urile duplicate folosind un dicționar standard
const uniquePdfsObj = {};
for (let i = 0; i < pdfLinks.length; i++) {
  uniquePdfsObj[pdfLinks[i].url] = pdfLinks[i];
}
const uniquePdfs = Object.values(uniquePdfsObj);

// Construim datele pentru următorul nod
const results = [];

// Adăugăm pagina web dacă are suficient text
if (cleanText.length > 100) {
  results.push({
    json: {
      type: "web_page",
      text: cleanText,
      source_url: baseUrl,
      fileName: "inginerie_dep_cie_page.txt",
      char_count: cleanText.length
    }
  });
}

// Adăugăm fișierele PDF
for (let j = 0; j < uniquePdfs.length; j++) {
  results.push({
    json: {
      type: "pdf_link",
      url: uniquePdfs[j].url,
      fileName: uniquePdfs[j].fileName,
      source_page: baseUrl
    }
  });
}

// MĂSURĂ DE SIGURANȚĂ: Dacă nu s-a găsit nimic, forțăm trimiterea pe ramură
// astfel încât nodul decizional ("E text?") să preia comanda.
if (results.length === 0) {
  results.push({
    json: {
      type: "web_page_short",
      text: cleanText,
      source_url: baseUrl,
      fileName: "inginerie_dep_cie_page.txt",
      char_count: cleanText.length
    }
  });
}

return results;

const item = $input.first().json;

return [{
  json: {
    text: item.text,
    metadata: {
      source_file: item.fileName,
      source_url: item.source_url,
      file_type: 'web',
      ingested_at: new Date().toISOString(),
      char_count: item.char_count
    }
  }
}];

const item = $input.first().json;
const previousItem = $('Download PDF').first().json;

return [{
  json: {
    text: item.text || item.data || '',
    metadata: {
      source_file: previousItem.fileName || 'document.pdf',
      source_url: previousItem.url || '',
      file_type: 'pdf',
      ingested_at: new Date().toISOString(),
      char_count: (item.text || '').length
    }
  }
}];
